const LOCATION_A = { province: 'Hà Nội', ward: 'Phường Cầu Giấy', street: 'Phạm Văn Bạch' };
const LOCATION_B = { province: 'An Giang', ward: 'Phường Châu Đốc', street: 'Kênh Hòa Bình' };
const LOCATION_C = { province: 'Hồ Chí Minh', ward: 'Phường Test Hồ Chí Minh' };

/**
 * Helper: mở checkout mới + set địa chỉ Location A (deterministic 5-EVC context,
 * auto-apply CA4699). Dùng chung cho phần lớn TC — thay thế phụ thuộc vào IP-based
 * geo default (không ổn định giữa các môi trường/tester, xem vibe-locators-latest.md).
 */
async function setupCheckoutAtLocationA(page: import('@playwright/test').Page): Promise<CheckoutPage> {
  const productPage = new ProductPage(page);
  const checkoutPage = new CheckoutPage(page);

  await productPage.navigate();
  await productPage.clickMuaNgay();
  await checkoutPage.tickReceiveInvoice();
  await checkoutPage.selectAddress(LOCATION_A);

  return checkoutPage;
}

// ============================================================
// Group 1: Auto-apply & Context Switch
// TC_02.1, 2, 3, 4, 5, 13, 14, 15, 16
// ============================================================
test.describe('Auto-apply & Context Switch', () => {
  test('TC_02.1: Auto-apply voucher có DiscountVAT cao nhất khi lần đầu vào Thanh toán', async ({ page }) => {
    // Pre-condition: checkout có context đầy đủ, chưa có voucher, tài khoản có ≥2 EVC hợp lệ khác DiscountVAT
    const checkoutPage = await setupCheckoutAtLocationA(page);

    // Step 1-2: Truy cập URL màn Thanh toán, chờ tải xong, KHÔNG thao tác thêm
    // (setupCheckoutAtLocationA đã navigate + set context — chỉ còn quan sát)

    // Step 3: Quan sát block Voucher + dòng "Cần thanh toán"
    // Expected: CO tự áp đúng 1 EVC có DiscountVAT cao nhất (CA4699, 10.000đ — cao nhất trong 5 EVC)
    const codes = await checkoutPage.getAppliedVoucherCodes();
    expect(codes).toHaveLength(1);
    expect(codes[0]).toContain('CA4699GIAM10KPHIHOAMANG');

    // Expected: "Cần thanh toán" = giá gốc − discount = 39.900 − 10.000 = 29.900đ
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('29.900đ');
  });

  test('TC_02.2: Đổi context (chỉ voucher auto) → remove voucher cũ + apply best mới', async ({ page }) => {
    // Pre-condition: checkout đang có voucher V1 auto-apply; hasManualVoucher=false
    const checkoutPage = await setupCheckoutAtLocationA(page);
    await expect.poll(() => checkoutPage.getAppliedVoucherCount()).toBe(1);

    // Step 1: Đổi địa chỉ sang context mới (Location B — vẫn có EVC hợp lệ)
    await checkoutPage.selectAddress(LOCATION_B);

    // Step 2-3: Chờ xử lý lại, quan sát block voucher + "Cần thanh toán"
    // Expected: CO remove V1, tìm voucher tốt nhất context mới, apply, tính lại — không crash/stuck
    // (verified VR-004: badge 5→4, CO tự gọi lại apply mode=Auto; best vẫn CA4699 vì cao nhất ở cả 2 context)
    await expect.poll(() => checkoutPage.getVoucherBadgeCount()).toBe(4);
    await expect.poll(() => checkoutPage.getAppliedVoucherCodes()).toEqual(
      expect.arrayContaining([expect.stringContaining('CA4699GIAM10KPHIHOAMANG')])
    );
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('29.900đ');
  });

  test('TC_02.3: Giữ voucher còn valid sau khi đổi context (hasManualVoucher=true)', async ({ page }) => {
    // Pre-condition: hasManualVoucher=true (voucher manual đang áp); voucher vẫn hợp lệ với context mới
    const checkoutPage = await setupCheckoutAtLocationA(page);
    await checkoutPage.openVoucherModal();
    await checkoutPage.toggleVoucherInModal(0); // uncheck CA4699 (auto)
    await checkoutPage.toggleVoucherInModal(1); // check CA4431 (manual)
    await checkoutPage.confirmVoucherModal();
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('34.900đ');

    // Step 1: Đổi context (PTTT → Ví MoMo) — voucher CA4431 (General, không ràng buộc PTTT) vẫn hợp lệ
    await checkoutPage.selectPaymentMethod('Ví MoMo');

    // Step 2-3: FE apply lại [auto+manual], quan sát voucher + giá
    // Expected: CO GetEvoucherInfor + Recheck; voucher giữ nguyên trong checkout; giá tính với voucher đó
    await expect.poll(() => checkoutPage.getAppliedVoucherCodes()).toEqual(
      expect.arrayContaining([expect.stringContaining('CA4431GIAMTTUFSA03')])
    );
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('34.900đ');
  });

  test('TC_02.4: User bỏ voucher manual → giữ voucher auto, cập nhật hasManualVoucher', async ({ page }) => {
    // Pre-condition: checkout có cả voucher manual và auto (do BUG-001 stacking — 2 voucher cùng active)
    const checkoutPage = await setupCheckoutAtLocationA(page);
    await checkoutPage.openVoucherModal();
    await checkoutPage.toggleVoucherInModal(1); // thêm CA4431 (manual), KHÔNG bỏ CA4699 (auto)
    await checkoutPage.confirmVoucherModal();
    await expect.poll(() => checkoutPage.getAppliedVoucherCount()).toBe(2);

    // Step 1: Bỏ voucher manual (CA4431)
    await checkoutPage.openVoucherModal();
    await checkoutPage.toggleVoucherInModal(1); // uncheck CA4431
    await checkoutPage.confirmVoucherModal();

    // Step 2: Quan sát voucher còn lại + flag
    // Expected: CO chỉ remove voucher manual; voucher auto (CA4699) giữ nguyên
    const codes = await checkoutPage.getAppliedVoucherCodes();
    expect(codes).toHaveLength(1);
    expect(codes[0]).toContain('CA4699GIAM10KPHIHOAMANG');
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('29.900đ');
  });

  test('TC_02.5: Đổi context khi chỉ còn voucher manual → chỉ revalidate manual, không auto mới', async ({
    page,
  }) => {
    // Pre-condition: checkout chỉ còn voucher manual (auto đã bị bỏ); hasManualVoucher=true
    const checkoutPage = await setupCheckoutAtLocationA(page);
    await checkoutPage.openVoucherModal();
    await checkoutPage.toggleVoucherInModal(0); // uncheck CA4699 (auto)
    await checkoutPage.toggleVoucherInModal(1); // check CA4431 (manual)
    await checkoutPage.confirmVoucherModal();

    // Step 1: Đổi context → FE apply lại [manual]
    await checkoutPage.selectPaymentMethod('Ví MoMo');

    // Step 2: Quan sát voucher + có voucher auto mới không
    // Expected: CO GetEvoucherInfor + Recheck voucher manual; giữ nếu valid; KHÔNG apply voucher auto mới
    // (badge tăng 5→6 vì CA4887-Momo xuất hiện trong list, nhưng KHÔNG tự động được apply)
    await expect.poll(() => checkoutPage.getVoucherBadgeCount()).toBe(6);
    const codes = await checkoutPage.getAppliedVoucherCodes();
    expect(codes).toHaveLength(1);
    expect(codes[0]).toContain('CA4431GIAMTTUFSA03');
  });

  test('TC_02.13: hasManualVoucher=true → CO KHÔNG tự auto-apply khi đổi context', async ({ page }) => {
    // Pre-condition: checkout có ≥1 voucher manual + 1 auto (hasManualVoucher=true)
    const checkoutPage = await setupCheckoutAtLocationA(page);
    await checkoutPage.openVoucherModal();
    await checkoutPage.toggleVoucherInModal(0); // uncheck CA4699
    await checkoutPage.toggleVoucherInModal(1); // check CA4431 (manual)
    await checkoutPage.confirmVoucherModal();
    const priceBefore = await checkoutPage.getTotalPriceText();

    // Step 1: Đổi Gói/PTTT/địa chỉ
    await checkoutPage.selectPaymentMethod('Ví MoMo');

    // Step 2: Quan sát hành vi CO — không có voucher auto MỚI tự xuất hiện ngoài request FE
    // Expected: CO KHÔNG tự chạy auto-apply; giá giữ nguyên như trước khi đổi context
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe(priceBefore);
    await expect.poll(() => checkoutPage.getAppliedVoucherCount()).toBe(1);
  });

  test('TC_02.14: Không auto-apply voucher mới thay thế voucher bị remove', async ({ page }) => {
    // Pre-condition: voucher bị remove sau revalidate (hasManualVoucher=true)
    const checkoutPage = await setupCheckoutAtLocationA(page);
    await checkoutPage.selectPaymentMethod('Ví MoMo');
    await checkoutPage.openVoucherModal();
    const momoIndex = 3; // CA4887GIAMTTUFSA03MOMO — verify vị trí qua modal trước khi chạy thật
    await checkoutPage.toggleVoucherInModal(0); // uncheck CA4699 (auto)
    await checkoutPage.toggleVoucherInModal(momoIndex); // check CA4887 (manual, Momo-only)
    await checkoutPage.confirmVoucherModal();
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('34.900đ');

    // Step 1: Tạo trạng thái voucher bị remove sau đổi context (đổi PTTT khỏi Momo → CA4887 invalid)
    await checkoutPage.selectPaymentMethod('Thẻ ATM');

    // Step 2-3: Chờ CO xử lý xong, quan sát có voucher mới tự thay thế không
    // Expected: CO KHÔNG tự tìm + apply voucher mới thay thế (dù CA4699 10.000đ khả dụng lại);
    // "Cần thanh toán" về giá gốc (không có voucher nào còn lại)
    await expect.poll(() => checkoutPage.getAppliedVoucherCount()).toBe(0);
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('39.900đ');
  });

  test('TC_02.15: User bỏ voucher auto → remove, KHÔNG auto-apply lại', async ({ page }) => {
    // Pre-condition: checkout có voucher auto, không có manual
    const checkoutPage = await setupCheckoutAtLocationA(page);

    // Step 1: Bấm bỏ/xóa voucher auto (uncheck trong modal, Xác nhận = FE gọi Apply rỗng)
    await checkoutPage.openVoucherModal();
    await checkoutPage.toggleVoucherInModal(0); // uncheck CA4699
    await checkoutPage.confirmVoucherModal();

    // Step 2: Quan sát voucher + giá
    // Expected: CO remove voucher; dù hasManualVoucher=false, CO KHÔNG auto-apply lại; giá về giá gốc
    await expect.poll(() => checkoutPage.getAppliedVoucherCount()).toBe(0);
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('39.900đ');
  });

  test('TC_02.16: Sau khi user chủ động bỏ voucher + đổi context → KHÔNG auto-apply', async ({ page }) => {
    // Pre-condition: user vừa bỏ voucher; hasManualVoucher=false; còn EVC hợp lệ trong tài khoản
    const checkoutPage = await setupCheckoutAtLocationA(page);

    // Step 1: Bỏ voucher đang áp
    await checkoutPage.openVoucherModal();
    await checkoutPage.toggleVoucherInModal(0);
    await checkoutPage.confirmVoucherModal();
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('39.900đ');

    // Step 2-3: Đổi Gói/PTTT/địa chỉ, chờ CO nhận context change
    await checkoutPage.selectPaymentMethod('Ví MoMo');

    // Step 4: Quan sát block voucher + giá
    // Expected: CO KHÔNG auto-apply (user đã chủ động bỏ = quyết định không dùng); giá giữ giá gốc
    // (badge vẫn tăng 5→6 do list refresh theo PTTT, nhưng KHÔNG tự apply)
    await expect.poll(() => checkoutPage.getVoucherBadgeCount()).toBe(6);
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('39.900đ');
  });
});

