// Group 2: Manual Selection & Popup Behavior
// TC_02.8, 9, 36
// ============================================================
test.describe('Manual Selection & Popup Behavior', () => {
  test("TC_02.8: Chọn EVC hợp lệ + 'Đồng ý' → cập nhật giá giảm và tổng đơn", async ({ page }) => {
    // Pre-condition: popup danh sách EVC đang mở; checkout chưa áp voucher
    const checkoutPage = await setupCheckoutAtLocationA(page);
    await checkoutPage.openVoucherModal();
    await checkoutPage.toggleVoucherInModal(0); // uncheck CA4699 auto trước, để test chọn thủ công sạch
    await checkoutPage.confirmVoucherModal();
    await expect.poll(() => checkoutPage.getAppliedVoucherCount()).toBe(0);

    // Step 1: Chọn 1 EVC hợp lệ (click checkbox)
    await checkoutPage.openVoucherModal();
    await checkoutPage.toggleVoucherInModal(1); // CA4431

    // Step 2-3: Bấm "Đồng ý" (Xác nhận), chờ loading
    await checkoutPage.confirmVoucherModal();

    // Step 4: Quan sát màn Thanh toán sau khi popup đóng
    // Expected: popup đóng; số tiền giảm hiển thị; "Cần thanh toán" = giá gốc − discount; EVC "đang áp dụng"
    await expect.poll(() => checkoutPage.getSuccessMessageText()).toContain('Áp dụng mã ưu đãi thành công.');
    const codes = await checkoutPage.getAppliedVoucherCodes();
    expect(codes[0]).toContain('CA4431GIAMTTUFSA03');
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('34.900đ');
  });

  test('TC_02.9: Hủy EVC đang áp (uncheck + Đồng ý) → reset giá gốc, không call QLCS', async ({ page }) => {
    // Pre-condition: đã apply 1 EVC; màn hiển thị giá đã giảm
    const checkoutPage = await setupCheckoutAtLocationA(page);
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('29.900đ');

    // Step 1: Mở lại popup danh sách EVC
    await checkoutPage.openVoucherModal();

    // Step 2: Bỏ chọn EVC đang áp (uncheck)
    await checkoutPage.toggleVoucherInModal(0);

    // Step 3: Bấm "Đồng ý" xác nhận hủy
    await checkoutPage.confirmVoucherModal();

    // Step 4: Quan sát màn Thanh toán
    // Expected: "Cần thanh toán" = giá gốc (chính xác); số tiền giảm biến mất; EVC không còn "đang áp dụng"
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('39.900đ');
    await expect.poll(() => checkoutPage.getAppliedVoucherCount()).toBe(0);
  });

  test('TC_02.36: Đóng popup EVC (X) không thay đổi state checkout', async ({ page }) => {
    // Pre-condition: popup EVC mở; chưa thao tác chọn EVC trong lần này
    const checkoutPage = await setupCheckoutAtLocationA(page);
    const priceBefore = await checkoutPage.getTotalPriceText();
    await checkoutPage.openVoucherModal();

    // Step 1: Chọn 1 checkbox khác (thao tác trong modal, chưa confirm) rồi bấm X — KHÔNG confirm
    await checkoutPage.toggleVoucherInModal(2); // chọn thêm CA4580, chưa Xác nhận
    await checkoutPage.closeVoucherModal();

    // Step 2: Quan sát trạng thái màn Thanh toán
    // Expected: popup đóng; state checkout KHÔNG đổi (giá giữ nguyên như trước khi mở modal)
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe(priceBefore);
  });
});

