test.describe('PTTT-specific Voucher & Recheck', () => {
  test('TC_02.11: Lọc voucher theo điều kiện địa chỉ + PTTT + chu kỳ', async ({ page }) => {
    // Pre-condition: QLCS trả điều kiện theo địa chỉ/PTTT/chu kỳ; một số voucher không thỏa đơn
    const checkoutPage = await setupCheckoutAtLocationA(page);

    // Step 1: PTTT mặc định (Thẻ ATM) — CA4887 (Momo-only) KHÔNG xuất hiện
    await checkoutPage.openVoucherModal();
    await expect.poll(() => checkoutPage.getModalVoucherCount()).toBe(5);
    await checkoutPage.closeVoucherModal();

    // Step 2-3: Đổi PTTT = Momo, mở "Chọn ưu đãi", quan sát danh sách
    await checkoutPage.selectPaymentMethod('Ví MoMo');
    await checkoutPage.openVoucherModal();

    // Step 4-5: Đổi PTTT/địa chỉ/chu kỳ sang giá trị khác, quan sát danh sách cập nhật
    // Expected: danh sách CHỈ hiển thị voucher thỏa PTTT hiện tại; list cập nhật không chuyển màn
    await expect.poll(() => checkoutPage.getModalVoucherCount()).toBe(6); // +CA4887 Momo-only
  });

  test('TC_02.20: Remove voucher invalid sau đổi context + thông báo tiếng Việt', async ({ page }) => {
    // Pre-condition: hasManualVoucher=true; sau đổi context voucher X không còn hợp lệ
    const checkoutPage = await setupCheckoutAtLocationA(page);
    await checkoutPage.selectPaymentMethod('Ví MoMo');
    await checkoutPage.openVoucherModal();
    await checkoutPage.toggleVoucherInModal(0); // uncheck CA4699
    await checkoutPage.toggleVoucherInModal(3); // check CA4887 (Momo-only)
    await checkoutPage.confirmVoucherModal();

    // Step 1: Đổi PTTT khiến voucher X (CA4887) invalid
    await checkoutPage.selectPaymentMethod('Thẻ ATM');

    // Step 2-3: Chờ xử lý xong, quan sát thông báo + khu vực voucher
    // Expected: CO remove X, tính lại; hiển thị thông báo tiếng Việt; mã X + discount biến mất; giá về giá gốc
    await expect.poll(() => checkoutPage.isInvalidVoucherMessageVisible()).toBe(true);
    await expect.poll(() => checkoutPage.getAppliedVoucherCount()).toBe(0);
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('39.900đ');
  });

  test('TC_02.21: Đổi context, voucher manual invalid → remove + thông báo', async ({ page }) => {
    // Pre-condition: chỉ còn voucher manual; voucher manual không hợp lệ context mới
    const checkoutPage = await setupCheckoutAtLocationA(page);
    await checkoutPage.selectPaymentMethod('Ví MoMo');
    await checkoutPage.openVoucherModal();
    await checkoutPage.toggleVoucherInModal(0); // uncheck CA4699
    await checkoutPage.toggleVoucherInModal(3); // check CA4887 (manual, Momo-only)
    await checkoutPage.confirmVoucherModal();

    // Step 1: Đổi context khiến manual invalid (đổi PTTT khỏi Momo)
    await checkoutPage.selectPaymentMethod('Thẻ ATM');

    // Step 2-3: Chờ xử lý, quan sát voucher + thông báo + giá
    // Expected: CO nhận invalid, remove voucher manual, tính lại giá gốc, trả thông báo phù hợp
    await expect.poll(() => checkoutPage.isInvalidVoucherMessageVisible()).toBe(true);
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('39.900đ');
  });

  test('TC_02.24: Voucher đã áp không còn thỏa điều kiện (đổi PTTT) → tự xóa + reload list', async ({
    page,
  }) => {
    // Pre-condition: đã áp voucher V thỏa điều kiện hiện tại (PTTT=Momo)
    const checkoutPage = await setupCheckoutAtLocationA(page);
    await checkoutPage.selectPaymentMethod('Ví MoMo');
    await checkoutPage.openVoucherModal();
    await checkoutPage.toggleVoucherInModal(0); // uncheck CA4699
    await checkoutPage.toggleVoucherInModal(3); // check CA4887 (Momo-only)
    await checkoutPage.confirmVoucherModal();
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('34.900đ');

    // Step 1: Đổi PTTT sang khác Momo (V không còn thỏa)
    await checkoutPage.selectPaymentMethod('Thẻ ATM');

    // Step 2: Quan sát voucher + giá + danh sách
    // Expected: hệ thống tự XÓA voucher V; tính lại "Cần thanh toán"; danh sách reload chỉ còn voucher thỏa
    // điều kiện mới (badge về 5); có thông báo voucher bị gỡ; không chuyển màn
    await expect.poll(() => checkoutPage.getAppliedVoucherCount()).toBe(0);
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('39.900đ');
    await expect.poll(() => checkoutPage.getVoucherBadgeCount()).toBe(5);
    await expect(page).toHaveURL(/\/checkout\/.+\/payment/); // không chuyển màn
  });

  test('TC_02.6: Recheck lúc Thanh toán hợp lệ (result=1) → tạo order thành công', async ({ page }) => {
    // Pre-condition: đã apply EVC hợp lệ; Recheck sẽ trả result=1
    const checkoutPage = await setupCheckoutAtLocationA(page);
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('29.900đ');

    // Điền thông tin cá nhân bắt buộc trước khi submit (không phải step trong TC — pre-condition ngầm)
    await checkoutPage.fillPersonalInfo({
      phone: '0912345678',
      name: 'Nguyen Van A',
      email: 'nguyenvana@test.com',
    });
    await checkoutPage.selectAddress({ ...LOCATION_A, houseNumber: '123' });
    await checkoutPage.selectPaymentMethod('Thẻ ATM');

    // Step 1: Bấm "Thanh toán"
    await checkoutPage.clickThanhToan();

    // Step 2: Chờ xử lý — redirect sang cổng thanh toán FoxPay/Napas
    const paymentGateway = new PaymentGatewayPage(page);
    await paymentGateway.fillCard({
      number: '9704000000000018', // Thẻ test STG (SaigonBank/Napas) — CHỈ dùng trên STG
      name: 'NGUYEN VAN A',
      expiry: '03/07',
    });
    await paymentGateway.clickPay();
    await paymentGateway.submitOtp('otp');

    // Expected: Recheck trả 1; điều hướng qua màn thanh toán thành công (đơn tạo với voucher đã áp)
    await expect.poll(() => paymentGateway.isSuccessVisible()).toBe(true);
    await paymentGateway.close();

    const orderCompletedPage = new OrderCompletedPage(page);
    await expect.poll(() => orderCompletedPage.isSuccessVisible()).toBe(true);
    const voucherCodes = await orderCompletedPage.getAppliedVoucherCodes();
    expect(voucherCodes[0]).toContain('CA4699GIAM10KPHIHOAMANG');
  });
});

