// ============================================================
test.describe('UI Display & Structure', () => {
  test('TC_02.10: Block CTKM hiển thị count EVC khả dụng khi load màn hình', async ({ page }) => {
    // Pre-condition: có ≥1 EVC hợp lệ với context checkout
    const checkoutPage = await setupCheckoutAtLocationA(page);

    // Step 1-2: Truy cập màn Thanh toán, chờ tải xong (không thao tác)
    // Step 3: Quan sát khu vực block CTKM/Ưu đãi
    // Expected: block tự hiển thị số EVC khả dụng (số nguyên > 0); không cần bấm thêm; không lỗi
    await expect.poll(() => checkoutPage.getVoucherBadgeCount()).toBe(5);
  });

  test("TC_02.27: Trang Cart hiển thị link nhập mã ưu đãi (default chưa áp voucher)", async ({ page }) => {
    // Ghi chú (VR-001 clarification từ BA): "Cart page" = trang Checkout hiện tại; textbox
    // "Nhập mã khuyến mãi" chính là link nhập mã ưu đãi trong TC gốc.
    const checkoutPage = await setupCheckoutAtLocationA(page);

    // Step 1-3: Truy cập trang Cart, quan sát Thông tin thanh toán, tìm phần nhập mã ưu đãi
    // Expected: textbox nhập mã ưu đãi hiển thị dưới dòng Tạm tính
    await expect.poll(() => checkoutPage.isPromoCodeInputVisible()).toBe(true);
  });

  test("TC_02.28: Trang Checkout hiển thị section 'Chọn ưu đãi'/'Áp dụng' (default chưa áp)", async ({
    page,
  }) => {
    // Pre-condition: KH ở Checkout đầy đủ; chưa áp voucher; đã điền PTTT
    const productPage = new ProductPage(page);
    const checkoutPage = new CheckoutPage(page);
    await productPage.navigate();
    await productPage.clickMuaNgay();
    // KHÔNG chọn địa chỉ ở đây — verify default state trước khi voucher context được set

    // Step 1-3: Truy cập Checkout, quan sát section Thông tin thanh toán, ghi nhận trạng thái voucher
    // Expected: button "Chọn ưu đãi" hiện; "Áp dụng" disabled/dạng link; không hiện voucher/discount
    // trước khi user tương tác (button Áp dụng luôn disabled — chỉ enable khi gõ mã tay)
    await expect.poll(() => checkoutPage.isVoucherTriggerVisible()).toBe(true);
    await expect.poll(() => checkoutPage.isApplyPromoEnabled()).toBe(false);
  });

  test('TC_02.31: Modal Empty State khi không có voucher khả dụng', async ({ page }) => {
    // Pre-condition: đơn không có voucher khả dụng (API trả list rỗng)
    const productPage = new ProductPage(page);
    const checkoutPage = new CheckoutPage(page);
    await productPage.navigate();
    await productPage.clickMuaNgay();
    await checkoutPage.tickReceiveInvoice();
    await checkoutPage.selectAddress(LOCATION_C); // 0 EVC

    // Step 1-2: Click "Chọn ưu đãi", chờ modal mở
    await checkoutPage.openVoucherModal();

    // Step 3: Quan sát nội dung modal
    // Expected: modal mở, hiện empty state; KHÔNG có nút "Xác nhận"
    await expect.poll(() => checkoutPage.isModalEmptyStateVisible()).toBe(true);
    await expect.poll(() => checkoutPage.getModalEmptyStateText()).toContain(
      'Rất tiếc, quý khách không có mã ưu đãi.'
    );
    await expect.poll(() => checkoutPage.isModalConfirmButtonVisible()).toBe(false);
  });

  test('TC_02.33: Mobile sticky bottom bar hiển thị voucher đã áp', async ({ page }) => {
    // Pre-condition: viewport mobile (≤768px); đã áp voucher V
    await page.setViewportSize({ width: 390, height: 844 });
    const checkoutPage = await setupCheckoutAtLocationA(page);

    // Step 1-2: Truy cập Checkout trên mobile, áp dụng voucher (đã auto-apply CA4699 sẵn)
    await expect.poll(() => checkoutPage.getTotalPriceText()).toBe('29.900đ');

    // Step 3: Quan sát sticky bottom bar dưới màn
    // Expected: sticky bar hiện; "Cần thanh toán" trong bar = giá đã giảm; nút "Tiếp tục" active
    await expect.poll(() => checkoutPage.isMobileStickyBarVisible()).toBe(true);
  });

  test('TC_02.37: Block CTKM ẩn/disabled khi không có EVC hợp lệ', async ({ page }) => {
    // Pre-condition: không có EVC hợp lệ với context
    const productPage = new ProductPage(page);
    const checkoutPage = new CheckoutPage(page);
    await productPage.navigate();
    await productPage.clickMuaNgay();
    await checkoutPage.tickReceiveInvoice();
    await checkoutPage.selectAddress(LOCATION_C); // 0 EVC

    // Step 1-2: Truy cập màn Thanh toán, chờ tải xong
    // Step 3: Quan sát khu vực block CTKM
    // Expected: badge ẩn (0/không hiện số); màn vẫn hoạt động bình thường, không lỗi
    await expect.poll(() => checkoutPage.getVoucherBadgeCount()).toBe(0);
    await expect.poll(() => checkoutPage.isVoucherTriggerVisible()).toBe(true); // trigger vẫn hiện, chỉ mất badge
  });

  test("TC_02.38: Badge số EVC khả dụng hiển thị đúng trên nút 'Chọn ưu đãi'", async ({ page }) => {
    // Pre-condition: có N EVC hợp lệ (N=5 tại Location A)
    const checkoutPage = await setupCheckoutAtLocationA(page);

    // Step 1-2: Quan sát nút "Chọn ưu đãi", ghi nhận số badge
    // Expected: badge hiển thị đúng số N (integer dương)
    const badgeCount = await checkoutPage.getVoucherBadgeCount();
    expect(badgeCount).toBe(5);
    expect(badgeCount).toBeGreaterThan(0);
  });

  test('TC_02.40: Popup EVC mở từ cache, không gọi lại GetListEvoucher', async ({ page }) => {
    // Pre-condition: đang ở Checkout; block CTKM count > 0
    const listRequests: string[] = [];
    page.on('request', (req) => {
      if (req.url().includes('/voucher/list')) listRequests.push(req.url());
    });

    const checkoutPage = await setupCheckoutAtLocationA(page);
    // Step 1: Xác nhận GetListEvoucher đã gọi khi load trang
    expect(listRequests.length).toBe(1);

    // Step 2: Bấm block CTKM/"Xem ưu đãi"
    await checkoutPage.openVoucherModal();

    // Step 3-4: Quan sát popup mở + Network tab, kiểm nội dung từng EVC row
    // Expected: popup mở ngay; Network KHÔNG có request GetListEvoucher mới (dùng cache)
    expect(listRequests.length).toBe(1);
    await expect.poll(() => checkoutPage.getModalVoucherCount()).toBe(5);
  });
});
